import itertools

_PAIR = {
    frozenset(): 0.0,
    frozenset({0}): 0.6,
    frozenset({1}): 0.4,
    frozenset({0, 1}): 1.0,
}

_TRIPLE = {
    frozenset(): 0.0,
    frozenset({0}): 1.0,
    frozenset({1}): 2.0,
    frozenset({2}): 0.5,
    frozenset({0, 1}): 4.0,
    frozenset({0, 2}): 1.5,
    frozenset({1, 2}): 3.0,
    frozenset({0, 1, 2}): 5.5,
}


def test_two_features():
    got = solution.shapley_values(lambda S: _PAIR[frozenset(S)], 2)
    assert abs(got[0] - 0.6) < 1e-12 and abs(got[1] - 0.4) < 1e-12

def test_three_additive():
    got = solution.shapley_values(lambda S: float(len(S)), 3)
    assert all(abs(v - 1.0) < 1e-12 for v in got)

def test_non_additive_pair():
    table = dict(_PAIR)
    table[frozenset({0, 1})] = 0.9
    got = solution.shapley_values(lambda S: table[frozenset(S)], 2)
    assert abs(got[0] - 0.55) < 1e-12 and abs(got[1] - 0.35) < 1e-12

def test_efficiency():
    got = solution.shapley_values(lambda S: _TRIPLE[frozenset(S)], 3)
    assert abs(sum(got) - 5.5) < 1e-9

def test_dummy_player_gets_nothing():
    def value(S):
        S = frozenset(S)
        total = 0.0
        if 0 in S:
            total += 1.0
        if 1 in S:
            total += 2.0
        if 0 in S and 1 in S:
            total += 1.0
        return total
    got = solution.shapley_values(value, 3)
    assert abs(got[2]) < 1e-12

def test_zero_players():
    assert solution.shapley_values(lambda S: 0.0, 0) == []

def test_negative_count_raises():
    try:
        solution.shapley_values(lambda S: 0.0, -1)
    except ValueError:
        return
    raise AssertionError("expected ValueError")
